def import_existing_batches(apps, schema_editor):
    Campaign = apps.get_model('promoforge', 'Campaign')
    Promotion = apps.get_model('promoforge', 'Promotion')
    database = schema_editor.connection.alias
    promotions = Promotion.objects.using(database).exclude(
        configuration__batch_id__isnull=True,
    ).exclude(configuration__batch_id='')
    batches = {}
    for promotion in promotions.iterator():
        key = (promotion.owner_id, promotion.configuration['batch_id'])
        batches.setdefault(key, []).append(promotion)

    for (owner_id, batch_id), items in batches.items():
        items.sort(key=lambda item: (
            item.configuration.get('product_index', item.id),
            item.id,
        ))
        artworks = []
        for item in items:
            configuration = item.configuration
            image_url = configuration.get('image_url', '')
            artworks.append({
                'promotion_id': item.id,
                'index': configuration.get('product_index', len(artworks)),
                'product': {
                    'name': configuration.get('product_name', item.title),
                    'category': configuration.get('category', ''),
                    'price': configuration.get('price', ''),
                    'originalPrice': configuration.get('original_price', ''),
                    'discount': configuration.get('discount', ''),
                    'imageUrl': image_url,
                    'imageName': configuration.get('image_name', ''),
                    'sourceImageUrl': image_url,
                    'image_asset_id': configuration.get('image_asset_id'),
                },
                'config': configuration.get('editor', {}),
                'status': 'ready',
                'error': None,
                'imageWarning': configuration.get('image_warning') or None,
            })
        title = items[0].configuration.get('campaign_name') or items[0].title
        campaign = Campaign.objects.using(database).create(
            owner_id=owner_id,
            name=f'Campanha · {title}'[:180],
            batch_id=batch_id,
            artworks=artworks,
        )
        Promotion.objects.using(database).filter(
            id__in=[item.id for item in items],
        ).update(campaign_id=campaign.id)


